cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv3d_khkw1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bs,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int Din,
    int Cout, int KH, int KW,
    int stride, int padding, int dilation,
    int groups,
    int Hout, int Wout, int Dout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 16;

  const int IC_per_group = Cin  / groups;
  const int OC_per_group = Cout / groups;

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;

  const int P_total = Hout * Wout * Dout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides for X: (Cin, H, Win, Din) contiguous
  const int64_t sXn = (int64_t)Cin * H * Win * Din;
  const int64_t sXc = (int64_t)H * Win * Din;
  const int64_t sXh = (int64_t)Win * Din;
  const int64_t sXw = (int64_t)Din;

  // Strides for Y: (Cout, Hout, Wout, Dout) contiguous
  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win, Din),
      make_stride(sXc, sXh, sXw, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout, Dout),
      make_stride(sYc, sYh, sYw, Int<1>{})
  );

  // Weight shape (Cout, IC_per_group, KH, KW) contiguous
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, IC_per_group, KH, KW),
      make_stride(IC_per_group * KH * KW, KH * KW, KW, Int<1>{})
  );

  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, IC_per_group, KH, KW),
      make_stride(IC_per_group * KH * KW, KH * KW, KW, Int<1>{})
  );

  // Load weights for this oc-block into shared memory
  const int wsize = OcPerBlock * IC_per_group * KH * KW;
  for (int idx = tid; idx < wsize; idx += Threads) {
    int rem = idx;
    int kw  = rem % KW;  rem /= KW;
    int kh  = rem % KH;  rem /= KH;
    int ic  = rem % IC_per_group; rem /= IC_per_group;
    int occ = rem;
    int oc  = oc_base + occ;

    T val = T(0);
    if (oc < Cout) {
      val = mW(oc, ic, kh, kw);
    }
    sW(occ, ic, kh, kw) = val;
  }
  __syncthreads();

  // Precompute per-p output coordinates
  int  p_idx[PVec];
  int  oh_arr[PVec], ow_arr[PVec], od_arr[PVec];
  int  id_arr[PVec];
  bool id_valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od  = p % Dout;
      int tmp = p / Dout;
      int ow  = tmp % Wout;
      int oh  = tmp / Wout;

      oh_arr[i] = oh;
      ow_arr[i] = ow;
      od_arr[i] = od;

      int id = od * stride - padding;
      id_arr[i]   = id;
      id_valid[i] = (id >= 0 && id < Din);
    } else {
      oh_arr[i] = ow_arr[i] = od_arr[i] = 0;
      id_arr[i] = -1;
      id_valid[i] = false;
    }
  }

  // Accumulators, initialize with bias
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (Bs != nullptr && oc < Cout) {
      bval = (float)Bs[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }

  const int group_id        = oc_base / OC_per_group;
  const int ic_base_global  = group_id * IC_per_group;

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    if (!id_valid[i]) continue;

    int id = id_arr[i];
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int ic = 0; ic < IC_per_group; ++ic) {
      int ic_global = ic_base_global + ic;
      for (int kh = 0; kh < KH; ++kh) {
        int ih = oh * stride - padding + kh * dilation;
        if ((unsigned)ih >= (unsigned)H) continue;
        for (int kw = 0; kw < KW; ++kw) {
          int iw = ow * stride - padding + kw * dilation;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)mX(ic_global, ih, iw, id);

          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            float wval = (float)sW(occ, ic, kh, kw);
            acc[occ][i] += xval * wval;
          }
        }
      }
    }
  }

  // Store results
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc, oh_arr[i], ow_arr[i], od_arr[i]) = static_cast<T>(acc[occ][i]);
    }
  }
}

torch::Tensor conv3d_khkw1_forward(torch::Tensor x,
                                    torch::Tensor w,
                                    c10::optional<torch::Tensor> b,
                                    int stride, int padding, int dilation,
                                    int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, H, W, D]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, KH, KW, 1]");
  TORCH_CHECK(w.size(4) == 1, "This kernel only supports kernel depth = 1");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  int64_t Din = x.size(4);

  int64_t Cout = w.size(0);
  int64_t ICg  = w.size(1);
  int64_t KH   = w.size(2);
  int64_t KW   = w.size(3);

  TORCH_CHECK(Cin / groups == ICg, "weight in-channels mismatch with groups");
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H   + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  int64_t Dout = (Din + 2 * padding - dilation * (1  - 1) - 1) / stride + 1;

  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 16;

  const int64_t P_total = Hout * Wout * Dout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)OcPerBlock * ICg * KH * KW * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_khkw1_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win, (int)Din,
      (int)Cout, (int)KH, (int)KW,
      (int)stride, (int)padding, (int)dilation,
      (int)groups,
      (int)Hout, (int)Wout, (int)Dout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_khkw1_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_khkw1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_khkw1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with an asymmetric kernel (kernel_size x kernel_size x 1),
    implemented with a single custom CUDA kernel written using CuTe tensors.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False) -> None:
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        IC_per_group = self.in_channels // self.groups
        K = self.kernel_size

        # Weight shape matches PyTorch Conv3d layout:
        # [Cout, Cin/groups, KH, KW, KD] with KD = 1
        self.weight = nn.Parameter(torch.empty(self.out_channels, IC_per_group, K, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_khkw1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

