#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv3d_khkw1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bs,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int Din,
    int Cout, int KH, int KW,
    int stride, int padding, int dilation,
    int groups,
    int Hout, int Wout, int Dout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 16;

  const int IC_per_group = Cin  / groups;
  const int OC_per_group = Cout / groups;

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;

  const int P_total = Hout * Wout * Dout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides for X: (Cin, H, Win, Din) contiguous
  const int64_t sXn = (int64_t)Cin * H * Win * Din;
  const int64_t sXc = (int64_t)H * Win * Din;
  const int64_t sXh = (int64_t)Win * Din;
  const int64_t sXw = (int64_t)Din;

  // Strides for Y: (Cout, Hout, Wout, Dout) contiguous
  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win, Din),
      make_stride(sXc, sXh, sXw, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout, Dout),
      make_stride(sYc, sYh, sYw, Int<1>{})
  );

  // Weight shape (Cout, IC_per_group, KH, KW) contiguous
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, IC_per_group, KH, KW),
      make_stride(IC_per_group * KH * KW, KH * KW, KW, Int<1>{})
  );

  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, IC_per_group, KH, KW),
      make_stride(IC_per_group * KH * KW, KH * KW, KW, Int<1>{})
  );

  // Load weights for this oc-block into shared memory
  const int wsize = OcPerBlock * IC_per_group * KH * KW;
  for (int idx = tid; idx < wsize; idx += Threads) {
    int rem = idx;
    int kw  = rem % KW;  rem /= KW;
    int kh  = rem % KH;  rem /= KH;
    int ic  = rem % IC_per_group; rem /= IC_per_group;
    int occ = rem;
    int oc  = oc_base + occ;

    T val = T(0);
    if (oc < Cout) {
      val = mW(oc, ic, kh, kw);
    }
    sW(occ, ic, kh, kw) = val;
  }
  __syncthreads();

  // Precompute per-p output coordinates
  int  p_idx[PVec];
  int  oh_arr[PVec], ow_arr[PVec], od_arr[PVec];
  int  id_arr[PVec];
  bool id_valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od  = p % Dout;
      int tmp = p / Dout;
      int ow  = tmp % Wout;
      int oh  = tmp / Wout;

      oh_arr[i] = oh;
      ow_arr[i] = ow;
      od_arr[i] = od;

      int id = od * stride - padding;
      id_arr[i]   = id;
      id_valid[i] = (id >= 0 && id < Din);
    } else {
      oh_arr[i] = ow_arr[i] = od_arr[i] = 0;
      id_arr[i] = -1;
      id_valid[i] = false;
    }
  }

  // Accumulators, initialize with bias
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (Bs != nullptr && oc < Cout) {
      bval = (float)Bs[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }

  const int group_id        = oc_base / OC_per_group;
  const int ic_base_global  = group_id * IC_per_group;

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    if (!id_valid[i]) continue;

    int id = id_arr[i];
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int ic = 0; ic < IC_per_group; ++ic) {
      int ic_global = ic_base_global + ic;
      for (int kh = 0; kh < KH; ++kh) {
        int ih = oh * stride - padding + kh * dilation;
        if ((unsigned)ih >= (unsigned)H) continue;
        for (int kw = 0; kw < KW; ++kw) {
          int iw = ow * stride - padding + kw * dilation;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)mX(ic_global, ih, iw, id);

          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            float wval = (float)sW(occ, ic, kh, kw);
            acc[occ][i] += xval * wval;
          }
        }
      }
    }
  }

